class Solution {
public:
    vector<int> missingRolls(vector<int>& rolls, int mean, int n) {
        int m = (int)rolls.size();
        long long total = (long long)(n + m) * mean;
        long long observed = 0;
        for (int r : rolls) observed += r;
        long long target = total - observed;

        if (target < n || target > 6LL * n) return {};

        vector<int> ans(n, 1);
        long long remaining = target - n;
        for (int i = 0; i < n && remaining > 0; i++) {
            long long add = min(5LL, remaining);
            ans[i] += (int)add;
            remaining -= add;
        }
        return ans;
    }
};
